"""Audio preprocessing helpers (denoise / vocal separation / scene split)."""

from .preprocess import cleanup_temps, light_denoise, preprocess_media, separate_vocals, stabilize_media_timeline, sweep_job_temps
from .scene_split import detect_coarse_scenes

# timing_pcm_cache imports numpy at module level — keep it lazy so CLI
# ``runtime ensure-*`` (via jobs → audio) does not self-lock native wheels.

__all__ = [
    "cleanup_temps",
    "default_timing_pcm_path",
    "detect_coarse_scenes",
    "last_written_timing_pcm",
    "light_denoise",
    "preprocess_media",
    "separate_vocals",
    "stabilize_media_timeline",
    "sweep_job_temps",
    "timing_pcm_cache_target",
    "write_mix_timing_pcm",
]

_TIMING_EXPORTS = {
    "default_timing_pcm_path",
    "last_written_timing_pcm",
    "timing_pcm_cache_target",
    "write_mix_timing_pcm",
}


def __getattr__(name: str):
    if name in _TIMING_EXPORTS:
        from . import timing_pcm_cache as _tpc

        return getattr(_tpc, name)
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")
